"""Item model and validation."""
from dataclasses import dataclass, asdict


@dataclass
class Item:
    sku: str
    name: str
    qty: int = 0
    location: str = "unsorted"

    def to_dict(self):
        return asdict(self)


def validate(item: Item) -> None:
    if not item.sku or " " in item.sku:
        raise ValueError("sku must be non-empty and contain no spaces")
    if not item.name.strip():
        raise ValueError("name must not be empty")
    if item.qty < 0:
        raise ValueError("qty must not be negative")

"""JSON-file storage. The file path is passed in, never hard-coded."""
import json
from pathlib import Path

from .items import Item, validate


def load(path):
    p = Path(path)
    if not p.exists():
        return {}
    data = json.loads(p.read_text(encoding="utf-8"))
    return {sku: Item(**row) for sku, row in data.items()}


def save(path, inventory):
    data = {sku: item.to_dict() for sku, item in sorted(inventory.items())}
    Path(path).write_text(json.dumps(data, indent=2), encoding="utf-8")


def add_item(path, item: Item):
    validate(item)
    inv = load(path)
    if item.sku in inv:
        inv[item.sku].qty += item.qty
    else:
        inv[item.sku] = item
    save(path, inv)
    return inv[item.sku]


def remove_qty(path, sku, qty):
    inv = load(path)
    if sku not in inv:
        raise KeyError(f"unknown sku: {sku}")
    if qty > inv[sku].qty:
        raise ValueError("not enough stock")
    inv[sku].qty -= qty
    save(path, inv)
    return inv[sku]

import io
import tempfile
import unittest
from pathlib import Path

from tidyshelf import cli, storage


class CliTests(unittest.TestCase):
    def setUp(self):
        self.dir = tempfile.TemporaryDirectory()
        self.db = str(Path(self.dir.name) / "shelf.json")

    def tearDown(self):
        self.dir.cleanup()

    def run_cli(self, *argv):
        out = io.StringIO()
        code = cli.main(["--db", self.db, *argv], out=out)
        return code, out.getvalue()

    def test_add_then_list(self):
        self.assertEqual(self.run_cli("add", "A-1", "Widget", "--qty", "4")[0], 0)
        code, text = self.run_cli("list")
        self.assertEqual(code, 0)
        self.assertIn("A-1\tWidget\t4", text)

    def test_add_twice_sums(self):
        self.run_cli("add", "A-1", "Widget", "--qty", "2")
        _, text = self.run_cli("add", "A-1", "Widget", "--qty", "3")
        self.assertIn("5 in stock", text)

    def test_remove_too_much_fails(self):
        self.run_cli("add", "A-1", "Widget", "--qty", "1")
        code, _ = self.run_cli("remove", "A-1", "--qty", "5")
        self.assertEqual(code, 1)

    def test_remove_unknown_fails(self):
        self.assertEqual(self.run_cli("remove", "ZZ")[0], 1)


class StorageTests(unittest.TestCase):
    def test_load_missing_file_is_empty(self):
        self.assertEqual(storage.load("/nonexistent/shelf.json"), {})


if __name__ == "__main__":
    unittest.main()

import unittest

from tidyshelf.items import Item, validate


class ValidateTests(unittest.TestCase):
    def test_ok(self):
        validate(Item("A-1", "Widget", 3))

    def test_space_in_sku(self):
        with self.assertRaises(ValueError):
            validate(Item("A 1", "Widget"))

    def test_negative_qty(self):
        with self.assertRaises(ValueError):
            validate(Item("A-1", "Widget", -1))

    def test_empty_name(self):
        with self.assertRaises(ValueError):
            validate(Item("A-1", "  "))


if __name__ == "__main__":
    unittest.main()

